    out = [row[:] for row in grid]
    four = [(r, c) for r, row in enumerate(grid) for c, v in enumerate(row) if v == 4]
    six = [(r, c) for r, row in enumerate(grid) for c, v in enumerate(row) if v == 6]
    if not four or not six:
        return out
    # 6 marker's placement indicates which adjacent reflection to draw.
    r0, r1 = min(r for r, c in four), max(r for r, c in four)
    c0, c1 = min(c for r, c in four), max(c for r, c in four)
    sr = (r0 + r1) / 2
    sc = (c0 + c1) / 2
    mr = sum(r for r, c in six) / len(six)
    mc = sum(c for r, c in six) / len(six)
    # Reflect perpendicular to the direction from the 4 object toward marker.
    for r, c in six:
        out[r][c] = 0
    if abs(mr - sr) >= abs(mc - sc):
        # Marker is primarily above/below: mirror across the nearest horizontal edge.
        if mr > sr:
            axis2 = 2 * r1 + 1
        else:
            axis2 = 2 * r0 - 1
        for r, c in four:
            rr = axis2 - r
            if 0 <= rr < len(out):
                out[rr][c] = 4
    else:
        # Marker is primarily left/right: mirror across nearest vertical edge.
        if mc > sc:
            axis2 = 2 * c1 + 1
        else:
            axis2 = 2 * c0 - 1
        for r, c in four:
            cc = axis2 - c
            if 0 <= cc < len(out[0]):
                out[r][cc] = 4
    return out
