    # (horizontal bar at an extreme, with its stem on one side) asks for a
    # left-right reflection, appended immediately to the right of the source.
    row_counts = {}
    for r, c in sixes:
        row_counts[r] = row_counts.get(r, 0) + 1
    max_count = max(row_counts.values())
    bar_rows = [r for r, n in row_counts.items() if n == max_count]
    rmin, rmax = min(row_counts), max(row_counts)
    is_t = len(bar_rows) == 1 and bar_rows[0] in (rmin, rmax)

    if is_t:
