        for r, c in fours:
            cc = 2 * right + 1 - c
            if 0 <= cc < len(out[0]):
                out[r][cc] = 4
    else:
        bottom = max(r for r, c in fours)
        for r, c in fours:
            rr = 2 * bottom + 1 - r
            if 0 <= rr < len(out):
                out[rr][c] = 4
    return out
