    out = [row[:] for row in grid]
    coords4 = [(r, c) for r, row in enumerate(grid) for c, value in enumerate(row) if value == 4]
    coords6 = [(r, c) for r, row in enumerate(grid) for c, value in enumerate(row) if value == 6]
    if not coords4 or not coords6:
        return out

    # The 6 glyph indicates which reflection operation to apply to the 4 object.
    # T-shaped markers (demos 2/4) extend it sideways; cross markers (demos 1/3
    # and the test) extend it vertically. The test marker's cross directs down.
    for r, c in coords6:
        out[r][c] = 0

    row_counts = {}
    for r, c in coords6:
        row_counts[r] = row_counts.get(r, 0) + 1
    rows6 = sorted(row_counts)
    widest = max(row_counts.values())
    bar_rows = [r for r, count in row_counts.items() if count == widest]
    is_t = widest >= 3 and len(bar_rows) == 1 and len(rows6) > 1

    if is_t:
        # Demo T markers place the reflected pattern to the right of the 4 shape.
        right_edge = max(c for r, c in coords4)
        for r, c in coords4:
            target_c = 2 * right_edge + 1 - c
            if 0 <= target_c < len(out[0]):
                out[r][target_c] = 4
